// Parse the ElevenLabs post-call webhook and prepare the signature check.
// Header format (confirmed on the first real event, 2026-10-18): "t=<unix>,v0=<hex hmac sha256 of `${t}.${rawBody}`>".
const item = $input.first();
const headers = item.json.headers || {};
const sig = String(headers['elevenlabs-signature'] || '');
const parts = Object.fromEntries(sig.split(',').map(p => { const i = p.indexOf('='); return [p.slice(0, i).trim(), p.slice(i + 1).trim()]; }));
const t = parts.t || '';
let raw = '';
if (item.binary && item.binary.data && item.binary.data.data) raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
let body = item.json.body;
if ((!body || typeof body !== 'object') && raw) { try { body = JSON.parse(raw); } catch (e) { body = {}; } }
body = body || {};
const d = body.data || {};
const a = d.analysis || {};
const dc = a.data_collection_results || {};
const v = k => (dc[k] && dc[k].value !== undefined && dc[k].value !== null) ? dc[k].value : '';
const asBool = x => x === true || String(x).toLowerCase() === 'true';
const now = Math.floor(Date.now() / 1000);
return [{ json: {
  signed: `${t}.${raw}`,
  v0: parts.v0 || '',
  fresh: !!t && Math.abs(now - Number(t)) < 1800,
  type: body.type || '',
  conversation_id: d.conversation_id || '',
  summary: String(a.transcript_summary || '').slice(0, 900),
  first_name: String(v('first_name') || ''),
  email: String(v('email') || '').trim(),
  phone: String(v('phone') || '').trim(),
  best_time: String(v('best_time') || ''),
  business_name: String(v('business_name') || ''),
  help_with: String(v('help_with') || '').slice(0, 500),
  hours_per_week: v('hours_per_week'),
  contact_preference: String(v('contact_preference') || 'none'),
  summary_consent: asBool(v('summary_consent')),
  wants_human_now: asBool(v('wants_human_now')),
  delete_request: asBool(v('delete_request')),
  duration_secs: (d.metadata && d.metadata.call_duration_secs) || 0
} }];

