// Decide whether the confirmation email may go out automatically.
// SEND_MODE 'test': only to internal addresses (@example.com). 'live': to any visitor who chose email.
// Flip to 'live' only after Steven has validated the test (DECISIONS 2026-10-18 "Auto-send confirmation").
const SEND_MODE = 'live'; // flip to 'live' after a validated test send
const lead = $('Has contact or wants a human?').item.json;
const email = String(lead.email || '').trim();
const validEmail = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email);
const internal = /@(example\.com)$/i.test(email);
const ok = validEmail && !lead.delete_request && lead.contact_preference === 'email' && (SEND_MODE === 'live' || internal);
return [{ json: { ...lead, email, send_ok: ok, send_mode: SEND_MODE, send_reason: ok ? 'sent' : (!validEmail ? 'invalid email' : lead.delete_request ? 'delete request' : SEND_MODE !== 'live' ? 'test mode (external address)' : 'not email') } }];
